{"code": "import os

# Check a few directories for valid JPEGs
valid_files = []
for dir_name in ['1', '2', '3', '4', '5']:
    dir_path = os.path.join("data_small", dir_name)
    if os.path.exists(dir_path):
        files = os.listdir(dir_path)
        for f in files:
            filepath = os.path.join(dir_path, f)
            if os.path.getsize(filepath) > 1000:
                with open(filepath, 'rb') as file:
                    header = file.read(2)
                    if header == b'\xff\xd8':
                        valid_files.append(os.path.join(dir_name, f))
                        print(f"Found: {dir_name}/{f}")
                        if len(valid_files) >= 3:
                            break
        if len(valid_files) >= 3:
            break

print(f"\nTotal valid files found: {len(valid_files)}")"}

